contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function containing the test logic
    // take a boolean parameter to vary the input space
    function run(bool dummy) public payable {
        // dummy is unused except to vary inputs; must exist per constraints

        // Make the state-changing call as its own top-level statement and capture revert status
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe C's balance after the call
        uint bal = address(c).balance;

        // Assert the general rule: either the call reverted or C's balance is zero
        assert(reverted || bal == 0);
    }

    receive() external payable {}
}

